PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?member_member ?memberName ?holding_holding ?holdingDateRange ?holdingStart ?holdingEnd WHERE {
  GRAPH ?memberGraph {

    ?member_member a agents:Member ; members:hasOfficeHolding ?holding_holding .
    OPTIONAL { ?member_member foaf:name ?memberName . }
    ?holding_holding a members:OfficeHolding ; members:heldOffice <https://data.oireachtas.ie/office/o-000002> .
    OPTIONAL {
      ?holding_holding members:hasMembershipDateRange ?holdingDateRange .
      ?holdingDateRange a members:DateRange .
      OPTIONAL { ?holdingDateRange members:StartDate ?holdingStart . }
      OPTIONAL { ?holdingDateRange members:EndDate ?holdingEnd . }
    }
  }
  FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
  GRAPH <https://data.oireachtas.ie/graph/offices> { <https://data.oireachtas.ie/office/o-000002> a members:NamedOffice ; skos:prefLabel ?officeLabel . }
} ORDER BY ?member_member ?memberName ?holding_holding ?holdingDateRange ?holdingStart ?holdingEnd LIMIT 100

