SELECT DISTINCT ?member ?memberName ?membership ?membershipRange ?membershipStart ?membershipEnd ?episode ?party ?partyLabel ?partyRange ?partyStart ?partyEnd ?affiliation ?affiliationLabel ?constituency ?term ?anchor ?anchor_membership ?anchorMembershipRange ?anchorMembershipStart ?anchorMembershipEnd ?holding ?holdingRange ?holdingStart ?holdingEnd WHERE {
GRAPH ?memberGraph { ?member a agents:Member . ?membership a members:DailMembership . ?episode a members:PartyMembership . ?member members:hasMembersMembership ?membership . ?membership members:inHouseTerm ?term . ?membership members:isRepresentativeFrom ?constituency . ?member members:hasMembersMembership ?episode . ?episode members:inOireachtasMembership ?membership . ?episode members:isPartyMembershipOf ?party . OPTIONAL { ?member foaf:name ?memberName . } OPTIONAL { ?membership members:hasMembershipDateRange ?membershipRange .
      ?membershipRange a members:DateRange .
      OPTIONAL { ?membershipRange members:StartDate ?membershipStart . }
      OPTIONAL { ?membershipRange members:EndDate ?membershipEnd . } } OPTIONAL { ?episode members:hasMembershipDateRange ?partyRange .
      ?partyRange a members:DateRange .
      OPTIONAL { ?partyRange members:StartDate ?partyStart . }
      OPTIONAL { ?partyRange members:EndDate ?partyEnd . } } } FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
GRAPH ?anchorGraph { ?anchor a agents:Member . VALUES ?anchor { <https://data.oireachtas.ie/ie/oireachtas/member/id/Bertie-Ahern.D.1977-07-05> } ?anchor_membership a members:DailMembership . ?holding a members:OfficeHolding . ?anchor members:hasMembersMembership ?anchor_membership . ?anchor_membership members:inHouseTerm ?term . ?anchor_membership members:isRepresentativeFrom ?constituency . ?anchor members:hasOfficeHolding ?holding . ?holding members:heldOffice ?office . OPTIONAL { ?anchor_membership members:hasMembershipDateRange ?anchorMembershipRange .
      ?anchorMembershipRange a members:DateRange .
      OPTIONAL { ?anchorMembershipRange members:StartDate ?anchorMembershipStart . }
      OPTIONAL { ?anchorMembershipRange members:EndDate ?anchorMembershipEnd . } } OPTIONAL { ?holding members:hasMembershipDateRange ?holdingRange .
      ?holdingRange a members:DateRange .
      OPTIONAL { ?holdingRange members:StartDate ?holdingStart . }
      OPTIONAL { ?holdingRange members:EndDate ?holdingEnd . } } } FILTER(STRSTARTS(STR(?anchorGraph), "https://data.oireachtas.ie/graph/member/"))
GRAPH <https://data.oireachtas.ie/graph/houses> { ?term a agents:DailTerm . }
GRAPH <https://data.oireachtas.ie/graph/constituencies> { ?constituency a members:DailConstituency . ?constituency members:constituencyInHouseTerm ?term . }
GRAPH <https://data.oireachtas.ie/graph/parties> { ?party a members:ParliamentaryParty . ?party members:activeDuringTerm ?term . OPTIONAL { ?party skos:prefLabel ?partyLabel . FILTER(LANG(?partyLabel) = "en") } }
OPTIONAL { GRAPH <https://data.oireachtas.ie/graph/political-affiliations/identities> { ?affiliation a members:PoliticalAffiliationIdentity . ?party members:hasPoliticalAffiliationIdentity ?affiliation . OPTIONAL { ?affiliation skos:prefLabel ?affiliationLabel . FILTER(LANG(?affiliationLabel) = "en") } } }
GRAPH <https://data.oireachtas.ie/graph/offices> { ?office a members:NamedOffice . VALUES ?office { <https://data.oireachtas.ie/office/o-000001> } }
FILTER(?member != ?anchor)
} ORDER BY ?affiliationLabel ?memberName ?partyStart ?membershipStart ?episode ?membership LIMIT 100

